// Adapt only these example mappings to your verified provider version. Never copy webhook tokens or base64 to output.
const PUBLIC_HOSTS = ['media.example.org']; // Replace with hosts you control and have verified allow anonymous, short-lived GETs.
const seen = $getWorkflowStaticData('global');
seen.whatsappAudioIds ??= {};
function directUrl(value) {
  if (typeof value !== 'string') return null;
  try {
    const u = new URL(value);
    if (u.protocol !== 'https:' || u.username || u.password || u.port || !PUBLIC_HOSTS.includes(u.hostname.toLowerCase())) return null;
    if (/\/(?:message\/download|chat\/getBase64FromMediaMessage)(?:\/|$)/i.test(u.pathname)) return null;
    return u.href;
  } catch { return null; }
}
function prepare(payload) {
  const p = payload?.body ?? payload ?? {};
  let provider, message, id, instance, isAudio, fromMe, candidate;
  if (p.EventType === 'messages' && p.message) {
    provider = 'uazapi'; message = p.message; id = message.id; instance = p.instanceName;
    isAudio = /^(?:audio|audiomessage)$/i.test(message.messageType ?? '');
    fromMe = message.fromMe === true;
    candidate = message.content?.directDownloadUrl; // User-supplied enrichment, not a guaranteed uazapi field.
  } else if (p.event === 'MESSAGES_UPSERT' && p.data) {
    provider = 'evolution'; message = p.data; id = message.key?.id; instance = p.instance;
    isAudio = message.messageType === 'audioMessage' || !!message.message?.audioMessage;
    fromMe = message.key?.fromMe === true;
    candidate = message.message?.mediaUrl; // May require auth; only use after host and anonymous GET verification.
  } else return { action: 'ignore', reason: 'unsupported_event' };
  if (!isAudio || fromMe || typeof id !== 'string' || !id || typeof instance !== 'string' || !instance) return { action: 'ignore', reason: 'not_incoming_audio_or_missing_id' };
  const key = `${provider}:${instance}:${id}`;
  if (seen.whatsappAudioIds[key]) return { action: 'ignore', reason: 'duplicate_id', provider, messageId: id };
  const url = directUrl(candidate);
  if (!url) return { action: 'needs_direct_url', reason: 'Provide a short-lived, anonymous HTTPS direct-download URL on an approved host; base64, localhost and provider API URLs are not accepted.', provider, messageId: id };
  // Small sequential-delivery cache. For concurrent or durable dedupe, use a data table with a unique message key.
  const now = Date.now();
  for (const [oldKey, when] of Object.entries(seen.whatsappAudioIds)) if (now - when > 7 * 86400000) delete seen.whatsappAudioIds[oldKey];
  if (Object.keys(seen.whatsappAudioIds).length >= 1000) delete seen.whatsappAudioIds[Object.keys(seen.whatsappAudioIds)[0]];
  seen.whatsappAudioIds[key] = now;
  return { action: 'transcribe', provider, messageId: id, actorInput: { urls: [url], fileConcurrency: 1, language: 'pt' } };
}
return $input.all().map(({ json }) => ({ json: prepare(json) }));

// Actor returns one Dataset row for this one-file run. Preserve the free failure details.
return $input.all().flatMap(({ json: row }) => {
  if (row.success !== true && row.success !== false) return [];
  return [{ json: { success: row.success, source: row.url ?? row.input ?? '', text: row.text ?? '', errorType: row.errorType ?? '', retryable: row.retryable === true, error: row.error ?? '' } }];
});
